head.script:
scwin.onpageunload = function() {};
scwin.fireOver = function(node) {
    if (document.createEventObject) {
        node.fireEvent('onmouseover');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('mouseover', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.onmouseover == 'function') {
        node.onmouseover();
    }
}
scwin.mouseOverBehaviour = function(id) {
    var el = WebSquare.wUnit.getDomById(id);
    scwin.fireOver(el);
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.mouseOverBehaviour('wq_uuid_3_headerRowStatus_bodyRow_0')", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wq_uuid_3_tooltip').css('display') == 'block'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wq_uuid_3_tooltip').text() == WebSquare.language.getMessage('Grid_rowStatus_update')", "true");
    WebSquare.wUnit.addCommand("set", "scwin.mouseOverBehaviour('wq_uuid_3_headerRowStatus_bodyRow_1')", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wq_uuid_3_tooltip').css('display') == 'block'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#wq_uuid_3_tooltip').text() == WebSquare.language.getMessage('Grid_rowStatus_insert')", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
scwin.onpageload = function() {
    window.initFnc = function() {
        dataList1.insertRow();
        dataList1.setCellData(0, "col2", "abc");
        dataList1.setCellData(1, "col3", "추가");
        dataList1.setCellData(1, "col1", "<-- 툴팁으로 '추가'표현");
    };
    initFnc();
}
